steps:
Run it:
```js
import assert from "node:assert/strict";
const clock = /^(?<hour>\d{2}):(?<minute>\d{2})$/;
const m = "14:05".match(clock);
assert.deepEqual({ ...m.groups }, { hour: "14", minute: "05" });
assert.equal(m[1], "14");                 // named groups are numbered too
assert.equal("9:5".match(clock), null);
assert.equal("14:05pm".match(clock), null);
console.log(m.groups.hour, m.groups.minute);
```
